import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000/api';

const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000,
});

// Request Interceptor
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    console.error('[API] Request Error:', error);
    return Promise.reject(error);
  }
);

// Response Interceptor
api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    console.error('[API] Response Error:', error);
    
    if (!error.response) {
      return Promise.reject({
        success: false,
        message: 'Lỗi mạng. Vui lòng kiểm tra kết nối.',
        code: 'NETWORK_ERROR'
      });
    }

    const { status, data } = error.response;
    let errorMessage = data?.message || 'Đã xảy ra lỗi';

    switch (status) {
      case 400:
        if (data?.errors) {
          errorMessage = Object.values(data.errors).flat().join(', ');
        } else if (data?.message) {
          errorMessage = data.message;
        }
        break;
      case 401:
        errorMessage = 'Phiên đăng nhập hết hạn';
        localStorage.removeItem('token');
        break;
      case 403:
        errorMessage = 'Bạn không có quyền truy cập';
        break;
      case 404:
        errorMessage = 'Không tìm thấy tài nguyên';
        break;
      case 500:
        errorMessage = 'Lỗi máy chủ';
        break;
    }

    return Promise.reject({
      success: false,
      message: errorMessage,
      code: `HTTP_${status}`,
      status,
      data
    });
  }
);

// API Auth
export const authAPI = {
  register: (userData) => api.post('/auth/signup', {
    username: userData.username?.trim(),
    email: userData.email?.toLowerCase().trim(),
    password: userData.password
  }),
  
  login: (credentials) => api.post('/auth/login', {
    email: credentials.email, // Đồng bộ với Login.js
    password: credentials.password
  }),
  
  logout: () => {
    localStorage.removeItem('token');
    return Promise.resolve();
  },
  
  getProfile: () => api.get('/auth/me') // Endpoint profile
};

// API Products
export const productAPI = {
  getProducts: (params) => api.get('/products', { params }),
  getProductDetails: (id) => api.get(`/products/${id}`),
  createProduct: (productData) => api.post('/products', productData),
  updateProduct: (id, productData) => api.put(`/products/${id}`, productData),
  deleteProduct: (id) => api.delete(`/products/${id}`)
};

export default api;
